+import { describe, expect, it, afterEach } from "bun:test";
+import { mkdtemp, writeFile } from "node:fs/promises";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { TokenStore, siteKey } from "./auth";
+import { resolveSiteUrl } from "./tools";
+
+const newStore = async () => new TokenStore(await mkdtemp(join(tmpdir(), "mp-")));
+
+const withToken = async (host: string, me: string) => {
+  const dir = await mkdtemp(join(tmpdir(), "mp-"));
+  await writeFile(join(dir, `${host}.json`), JSON.stringify({ me, access_token: "x" }));
+  return new TokenStore(dir);
+};
+
+afterEach(() => {
+  delete process.env.MICROPUB_SITE_URL;
+});
+
+describe("siteKey", () => {
+  it("keeps the port so local instances do not collide", () => {
+    expect(siteKey("http://localhost:3000")).not.toBe(siteKey("http://localhost:8080"));
+  });
+
+  it("avoids characters that are illegal in Windows filenames", () => {
+    expect(siteKey("http://localhost:3000")).toBe("localhost_3000");
+  });
+
+  it("leaves a site without a port unchanged", () => {
+    expect(siteKey("https://rmendes.net")).toBe("rmendes.net");
+  });
+});
+
+describe("resolveSiteUrl", () => {
+  it("prefers an explicit site_url over everything else", async () => {
+    process.env.MICROPUB_SITE_URL = "https://env.example";
+    const store = await withToken("only.example", "https://only.example");
+    expect(await resolveSiteUrl("http://localhost:3000", store)).toBe(
+      "http://localhost:3000"
+    );
+  });
+
+  it("falls back to MICROPUB_SITE_URL", async () => {
+    process.env.MICROPUB_SITE_URL = "http://localhost:3000";
+    const store = await withToken("only.example", "https://only.example");
+    expect(await resolveSiteUrl(undefined, store)).toBe("http://localhost:3000");
+  });
+
+  it("uses the only signed-in site, preserving scheme and port", async () => {
+    const store = await withToken("localhost:3000", "http://localhost:3000");
+    expect(await resolveSiteUrl(undefined, store)).toBe("http://localhost:3000");
+  });
+
+  it("refuses to guess when several sites are configured", async () => {
+    const dir = await mkdtemp(join(tmpdir(), "mp-"));
+    await writeFile(join(dir, "a.example.json"), JSON.stringify({ me: "https://a.example" }));
+    await writeFile(join(dir, "b.example.json"), JSON.stringify({ me: "https://b.example" }));
+    const store = new TokenStore(dir);
+    expect(resolveSiteUrl(undefined, store)).rejects.toThrow(/More than one site/);
+  });
+
+  it("never silently defaults to a live site when nothing is configured", async () => {
+    const store = await newStore();
+    expect(resolveSiteUrl(undefined, store)).rejects.toThrow(/Not signed in/);
+  });
+});

