+/**
+ * Work out which site a call is for.
+ *
+ * There is deliberately no hardcoded fallback: defaulting to a live site means a
+ * mistyped call publishes to production. If the target is ambiguous, fail and say
+ * what the options are.
+ */
+export async function resolveSiteUrl(
+  siteUrl?: string,
+  tokenStore: TokenStore = store
+): Promise<string> {
+  if (siteUrl) return siteUrl;
+
+  const fromEnv = process.env.MICROPUB_SITE_URL;
+  if (fromEnv) return fromEnv;
+
+  const hosts = await tokenStore.list();
+  if (hosts.length === 0) {
+    throw new Error(
+      "Not signed in to any site. Call micropub_auth with site_url=\"https://example.com\" first."
+    );
+  }
+  if (hosts.length === 1) {
+    const only = await tokenStore.load(hosts[0]!);
+    if (only?.me) return only.me;
+  }
+  throw new Error(
+    `More than one site is configured (${hosts.join(", ")}). ` +
+      "Pass site_url to choose one, or set MICROPUB_SITE_URL."
+  );
+}
